    /**
     * Ermittelt alle Dienststellen-Ordnungsnummern von bereits vorhanden Fachplanungen eines IT-Gesamtplanes.
     * @param GesamtPlan $gesamtPlan Gesamtplan
     * @return array
     */
    public static function getDienstStellenNummernVonGesamtplan(
        GesamtPlan $gesamtPlan
    ): array {
        $sql = "SELECT fk_dienststelle FROM fachplanung WHERE fk_gesamtplan = " . $gesamtPlan->jahr;
        $data = Page::db()->queryToArray($sql);
        $nummern = [];
        foreach ($data as $row) {
            $nummern[$row['fk_dienststelle']] = $row['fk_dienststelle'];
        }
        return $nummern;
    }

    /**
     * Gibt die gerade zuständige Dienststelle der Fachplanung zurück.
     * Gibt null zurück, wenn R1 gerade zuständig ist (dieser hat keine Dienststelle)
     * Wenn die Fachplanung geschlossen ist, wird auch false zurückgegeben.
     * @return DienstStelle|null gerade zuständige Dienststelle, null R1 ist zuständig
     */
    public function getZustaendigeDienststelle(): ?DienstStelle
    {
        if ($this->geschlossen) {
            return null;
        }
        $ressort = $this->dienstStelle->getParentRessort();
        return match ($this->redakteurLevel) {
            MemberShip::ACCESS_LEVEL_R3 => $this->dienstStelle,
            MemberShip::ACCESS_LEVEL_R2 => $ressort ?? $this->dienstStelle,
            //MemberShip::ACCESS_LEVEL_R2 => $ressort === null ?
            //    $this->dienstStelle : // Dienststelle ist Ressort
            //    $ressort, // Dienststelle ist einem Ressort untergeordnet
            default => null  // null ist R1
        };
    }

